"""Compile exact passenger-model descriptions from supplied vehicle-type tables."""

import argparse
import hashlib
import json
import os
import re
import sys
import tempfile
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from app.ista_data import DataFormatError, _kis_row, normalize_series

SCHEMA = (
    "CREATE CACHED TABLE KIS.FAHRZEUGTYP(ID INTEGER GENERATED BY DEFAULT AS "
    "IDENTITY(START WITH 1) NOT NULL,NAME CHARACTER(4) NOT NULL,EBR INTEGER NOT NULL,"
    "BESCHREIBUNG VARCHAR(1024),TYPMERKMALE VARCHAR(2048),TYPMERKMALE_PDM VARCHAR(2048),"
    "CONSTRAINT PK_EBR2BRV PRIMARY KEY(ID))"
)


def publish(path: Path, data: dict) -> None:
    """Atomically publish generated metadata without damaging an existing asset on failure."""
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-8", dir=path.parent, delete=False
        ) as stream:
            temporary = Path(stream.name)
            json.dump(data, stream, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def recover(ista: Path, output: Path, provenance: Path) -> None:
    """Decode every declared row, retaining only unambiguous exact BMW type matches."""
    root = ista / "Rheingold" if (ista / "Rheingold").is_dir() else ista
    models: dict[str, set[tuple[str, str]]] = {}
    sources = {}
    for script_path in sorted((root / "PSdZ/kiswb").glob("*/KIS.script")):
        script = script_path.read_text(encoding="utf-8")
        if SCHEMA not in script.splitlines():
            raise DataFormatError(f"Unexpected vehicle-type schema: {script_path}")
        match = re.search(r"^SET TABLE KIS.FAHRZEUGTYP INDEX '([\d ]+)'$", script, re.M)
        scale_match = re.search(r"^SET FILES SCALE (\d+)$", script, re.M)
        if match is None or scale_match is None:
            raise DataFormatError("Vehicle-type index or scale is missing")
        indexes = [int(value) for value in match[1].split()]
        scale = int(scale_match[1])
        if len(indexes) != 5 or not 0 <= indexes[-1] <= 100_000 or scale <= 0:
            raise DataFormatError("Unsupported vehicle-type index layout")
        data_path = script_path.with_name("KIS.data")
        size = data_path.stat().st_size
        seen: set[int] = set()
        pending = [indexes[0]] if indexes[-1] else []
        with data_path.open("rb") as stream:
            while pending:
                position = pending.pop()
                if position in seen or len(seen) >= indexes[-1]:
                    raise DataFormatError("Vehicle-type index is inconsistent")
                seen.add(position)
                row, left, right = _kis_row(
                    stream, position * scale, size, columns="isisss", indexes=2
                )
                pending.extend(value for value in (left, right) if value > 0)
                attributes = dict(
                    value.split("=", 1) for value in (row[4] or "").split(";") if "=" in value
                )
                series = normalize_series(attributes.get("EBR", ""))
                if attributes.get("MARKE") != "BM" or not re.fullmatch(r"[FGUI]\d{3}", series):
                    continue
                code, label = row[1], row[3]
                if label is None or not label.strip():
                    continue  # Nullable source descriptions stay unavailable.
                if not re.fullmatch(r"[A-Z0-9]{4}", code) or len(label) > 1024:
                    raise DataFormatError(
                        f"Invalid vehicle type: {script_path.parent.name} {code!r}"
                    )
                models.setdefault(code, set()).add((series, label))
        if len(seen) != indexes[-1]:
            raise DataFormatError("Vehicle-type row count differs from its index")
        with data_path.open("rb") as stream:
            data_hash = hashlib.file_digest(stream, "sha256").hexdigest()
        sources[script_path.parent.name] = {
            "script_sha256": hashlib.sha256(script_path.read_bytes()).hexdigest(),
            "data_sha256": data_hash,
            "rows": len(seen),
        }
    if not sources or not models:
        raise DataFormatError("No vehicle-type catalogue was recovered")
    data = {
        "schema": 1,
        "models": {
            code: [{"series": series, "label": label} for series, label in sorted(rows)]
            for code, rows in sorted(models.items())
        },
    }
    publish(output, data)
    publish(
        provenance,
        {
            "sources": sources,
            "types": len(models),
            "asset_sha256": hashlib.sha256(output.read_bytes()).hexdigest(),
        },
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("ista", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("provenance", type=Path)
    args = parser.parse_args()
    recover(args.ista, args.output, args.provenance)
